    def test_main_advance_before_build_rejects_stale_plan(self):
        self.github.main = "b" * 40
        self.assert_rejected("execution-time main")
        self.assertFalse(any(call[0][:3] == ["docker", "buildx", "build"] for call in self.fake.calls))

    def test_main_advance_during_push_never_creates_candidate(self):
        def advance(argv, cwd=None, env=None):
            result = self.fake(argv, cwd, env)
            if argv[:3] == ["docker", "buildx", "build"]:
                self.github.main = "b" * 40
            return result
        with self.assertRaisesRegex(ValueError, "execution-time main"):
            issuer.issue(self.root, self.plan, self.output, advance)
